// ValidateConnectionsField perform extra validation on the connections field which is not possible automatically by swagger
func ValidateConnectionsField(connections []api.Connection) *api.Error {
	if connections == nil {
		return nil
	}

	usedToolName := datastructs.Set[string]{}

	servingPortCounter := 0
	for _, connection := range connections {

		if usedToolName.Has(connection.Name) {
			return api.NewValidationError(fmt.Sprintf("tool name '%s' is used by multiple connections, should be unique", connection.Name))
		} else {
			usedToolName.Add(connection.Name)
		}
		if connection.IsExternal {
			if connection.InternalToolInfo != nil {
				return api.NewValidationError("InternalToolInfo should not be provided for external tools")
			}
			if connection.ExternalToolInfo == nil {
				return api.NewValidationError("externalToolInfo is mandatory for external tool")
			}
		} else {
			if connection.ExternalToolInfo != nil {
				return api.NewValidationError("externalToolInfo should not be provided for internal tools")
			}
			if connection.InternalToolInfo == nil {
				return api.NewValidationError("InternalToolInfo is mandatory for internal tool")
			}

			switch connection.InternalToolInfo.ConnectionType {
			case api.INTERNALCONNECTIONTYPE_EXTERNAL_URL:
				if connection.InternalToolInfo.NodePortInfo != nil {
					return api.NewValidationError("nodePortInfo should not be provided for ExternalUrl connection")
				}
			case api.INTERNALCONNECTIONTYPE_SERVING_PORT:
				if connection.InternalToolInfo.ServingPortInfo != nil && connection.InternalToolInfo.ServingPortInfo.Protocol != nil {
					protocolValue := convutils.Deref(connection.InternalToolInfo.ServingPortInfo.Protocol, constants.ProtocolHTTP)
					switch protocolValue {
					case constants.ProtocolGRPC, constants.ProtocolHTTP:
						if servingPortCounter > 0 {
							return api.NewValidationError("only one serving port is allowed")
						}
						servingPortCounter++
						continue
					default:
						return api.NewError(http.StatusBadRequest, fmt.Sprintf("unsupported value '%s' for field 'protocol'.", protocolValue), nil)
					}
				}
			case api.INTERNALCONNECTIONTYPE_NODE_PORT:
				if connection.InternalToolInfo.ExternalUrlInfo != nil {
					return api.NewValidationError("externalUrlInfo should not be provided for NodePort connection")
				}

			case api.INTERNALCONNECTIONTYPE_LOAD_BALANCER:
				if connection.InternalToolInfo.ExternalUrlInfo != nil {
					return api.NewValidationError("externalUrlInfo should not be provided for LoadBalancer connection")
				}
				if connection.InternalToolInfo.NodePortInfo != nil {
					return api.NewValidationError("nodePortInfo should not be provided for LoadBalancer connection")
				}
			}
		}
	}

	return nil
}

func validateSpecificEnv(workloadType string, workloadAssets []dbmodel.AssetsContainedInWorkload, specificEnv *api.SpecificRunParams) *api.Error {
	//
	//   look for the environment asset
	//
	var envAsset *dbmodel.EnvironmentAssetRec
	for _, assetPtrs := range workloadAssets {
		if assetPtrs.AssetsEnvironment != nil {
			envAsset = assetPtrs.AssetsEnvironment
		}
	}
	if envAsset == nil {
		return api.NewValidationError("environment asset is not selected, cannot create workload")
	}

	if specificEnv != nil {
		// need to make sure specific env does not violate OverrideUidGidInWorkspace field of the environment asset
		if !envAsset.OverrideUidGidInWorkspace {
			if specificEnv.RunAsUid != nil {
				return api.NewValidationError("it is not permitted to override the runAsUid from the environment asset")
			}
			if specificEnv.RunAsGid != nil {
				return api.NewValidationError("it is not permitted to override the runAsGid from the environment asset")
			}
			if specificEnv.SupplementalGroups != nil {
				return api.NewValidationError("it is not permitted to override the supplementalGroups from the environment asset")
			}
		}

		validationErr := validateEnvironmentVars(specificEnv.EnvironmentVariables)
		if validationErr != nil {
			return validationErr
		}
	}

	//
	//   if runAsUser is requested in the environment asset, runAsUid must have value
	//
	runAsUid, runAsGid, supplementalGroups, convErr := flat_workloads.DetermineUidAndGid(specificEnv, envAsset.EnvironmentAssetSpec)
	if convErr != nil {
		return convErr
	}

	err := validateUidGidFields(&envAsset.EnvironmentAssetSpec, runAsUid, runAsGid, supplementalGroups)
	if err != nil {
		return nil
	}

	//
	//   all the rest is validation of connections. with no connections in the asset, nothing more to validate
	//
	if envAsset.Connections == nil {
		return nil
	}

	//
	//   make sure that connections that appear in the specific env match those of the environment asset
	//
	if specificEnv != nil {
		redundantErr := ValidateSpecEnvConnNamesVsEnvAsset(specificEnv.Connections, envAsset.Connections)
		if redundantErr != nil {
			return redundantErr
		}
	}

	connSpecEnvById := map[string]api.SpecificRunConnectionInfo{}
	if specificEnv != nil && specificEnv.Connections != nil {
		for _, connSpecEnv := range *specificEnv.Connections {
			connSpecEnvById[connSpecEnv.Name] = connSpecEnv
		}
	}

	usedPorts := map[int32]string{}

	for _, connection := range envAsset.Connections {
		if connection.IsExternal || connection.InternalToolInfo == nil {
			continue
		}

		specEnvOfConn := connSpecEnvById[connection.Name]

		//
		//  validate existence of port value for custom ports, and ports uniqueness
		//
		if connection.InternalToolInfo.NodePortInfo != nil {
			if connection.InternalToolInfo.NodePortInfo.IsCustomPort {
				if specEnvOfConn.NodePort == nil {
					return api.NewValidationError(fmt.Sprintf("node port is mandatory for connection '%s'", connection.Name))
				}
				usedBy := usedPorts[*specEnvOfConn.NodePort]
				if usedBy != "" {
					return api.NewValidationError(fmt.Sprintf("node port %v is used by both '%s' and '%s' connections", *specEnvOfConn.NodePort, connection.Name, usedBy))
				}
				usedPorts[*specEnvOfConn.NodePort] = connection.Name
			}
		}

		//
		//  validate existence of url value for custom urls OR of ingress URL for auto generated urls
		//
		if connection.InternalToolInfo.ExternalUrlInfo != nil {
			if connection.InternalToolInfo.ExternalUrlInfo.IsCustomUrl {
				if convutils.IsEmptyOrNull(specEnvOfConn.ExternalUrl) && convutils.IsEmptyOrNull(connection.InternalToolInfo.ExternalUrlInfo.ExternalUrl) {
					return api.NewValidationError(fmt.Sprintf("url is mandatory for connection '%s'", connection.Name))
				}
			}
		}

		if specEnvOfConn.AuthorizedUsers != nil && specEnvOfConn.AuthorizedGroups != nil {
			return api.NewValidationError("authorizedUsers and authorizedGroups are mutually exclusive")
		}

		if specEnvOfConn.AuthorizedUsers != nil {
			if connection.InternalToolInfo == nil || connection.InternalToolInfo.ConnectionType != api.INTERNALCONNECTIONTYPE_EXTERNAL_URL {
				return api.NewValidationError(fmt.Sprintf("authorizedUsers is only supported with %s", api.INTERNALCONNECTIONTYPE_EXTERNAL_URL))
			}
		}

		if specEnvOfConn.AuthorizedGroups != nil {
			if connection.InternalToolInfo == nil || connection.InternalToolInfo.ConnectionType != api.INTERNALCONNECTIONTYPE_EXTERNAL_URL {
				return api.NewValidationError(fmt.Sprintf("authorizedGroups is only supported with %s", api.INTERNALCONNECTIONTYPE_EXTERNAL_URL))
			}
		}
	}

	if specificEnv != nil && specificEnv.AutoScaling != nil {
		if err := ValidateSpecEnvAutoScalingFields(workloadType, specificEnv.AutoScaling); err != nil {
			return err
		}
	}

	return nil
}

func validateEnvironmentVars(vars *[]api.EnvironmentVariableOfAsset) *api.Error {
	if vars == nil {
		return nil
	}

	usedNames := datastructs.Set[string]{}

	for _, envVar := range *vars {
		envName := convutils.Deref(envVar.Name, "")
		if usedNames.Has(envName) {
			return api.NewValidationError(fmt.Sprintf("duplicate variable name '%s'", envName))
		}
		usedNames.Add(envName)
		// Verify that the env var has at most one of value source (value/secret/credential)
		// It's ok not to provide any value, the value will be calculated when the workload is submitted
		score := 0
		if envVar.Value != nil {
			score++
		}
		if envVar.Credential != nil {
			score++

			if !convutils.IsStringHasValue(envVar.Credential.AssetId) {
				return api.NewValidationError(fmt.Sprintf("mandatory credential assetId is not provided for environment variable '%s'", envName))
			}
			if !convutils.IsStringHasValue(envVar.Credential.Key) {
				return api.NewValidationError(fmt.Sprintf("mandatory credential key is not provided for environment variable '%s'", envName))
			}
		}
		if envVar.ConfigMap != nil {
			score++

			if !convutils.IsStringHasValue(envVar.ConfigMap.Name) {
				return api.NewValidationError(fmt.Sprintf("mandatory configMap name is not provided for environment variable '%s'", envName))
			}
			if !convutils.IsStringHasValue(envVar.ConfigMap.Key) {
				return api.NewValidationError(fmt.Sprintf("mandatory configMap key is not provided for environment variable '%s'", envName))
			}
		}
		if score > 1 {
			return api.NewValidationError(fmt.Sprintf("environment variable '%s' must have only one of the following: value, credential, configMap", envName))
		}
	}

	return nil
}

// ValidateSpecEnvConnNamesVsEnvAsset makes sure that connection names appearing in the specific env also appear in the
// environment asset from which the workload or template is created.
func ValidateSpecEnvConnNamesVsEnvAsset(specEnvConnections *[]api.SpecificRunConnectionInfo, envAssetConnections []api.Connection) *api.Error {
	if specEnvConnections == nil {
		return nil
	}

	connNameInAsset := datastructs.Set[string]{}
	for _, envConnection := range envAssetConnections {
		connNameInAsset.Add(envConnection.Name)
	}

	for _, specEnvConnection := range *specEnvConnections {
		if !connNameInAsset.Has(specEnvConnection.Name) {
			return api.NewValidationError(fmt.Sprintf("connection named '%s' is not defined in the environment asset", specEnvConnection.Name))
		}
	}
	return nil
}

func ValidateEnvironmentRequestSpec(spec api.EnvironmentAssetSpec) *api.Error {
	validationError := ValidateConnectionsField(spec.Connections)
	if validationError != nil {
		return validationError
	}

	validationError = validateEnvironmentVars(spec.EnvironmentVariables)
	if validationError != nil {
		return validationError
	}

	err := validateUidGidFields(&spec, spec.RunAsUid, spec.RunAsGid, spec.SupplementalGroups)
	if err != nil {
		return err
	}

	if spec.Capabilities != nil {
		for _, capability := range *spec.Capabilities {
			if !capability.IsValid() {
				return api.NewValidationError(fmt.Sprintf("unsupported value '%s' for field 'Capability'.", capability))
			}
		}
	}

	return nil
}

func validateSelectedType(workloadSupportedTypes *api.WorkloadSupportedTypes) *api.Error {
	if workloadSupportedTypes == nil {
		return api.NewValidationError("you must specify environment supported types")
	}

	if convutils.BoolIsTrue(workloadSupportedTypes.Distributed) &&
		(workloadSupportedTypes.DistFramework == nil || *workloadSupportedTypes.DistFramework == "") &&
		convutils.BoolIsFalse(workloadSupportedTypes.Inference) {
		return api.NewValidationError("you must specify a DistFramework value when setting the type to Distributed")
	}

	// if DistFramework is set, Distributed must be true
	if workloadSupportedTypes.DistFramework != nil && *workloadSupportedTypes.DistFramework != "" &&
		(workloadSupportedTypes.Distributed == nil || (workloadSupportedTypes.Distributed != nil && convutils.BoolIsFalse(workloadSupportedTypes.Distributed))) {
		return api.NewValidationError("you need to provide a Distributed value when using the DistFramework")
	}
	return nil
}

// validateUidGidFields checks the uid/gid related fields. the function is used for checking both spec and specific env
// therefore it receives the values as separate parameters and does not take the value from the spec itself.
func validateUidGidFields(spec *api.EnvironmentAssetSpec, runAsUid *int64, runAsGid *int64, supplementalGroups *string) *api.Error {
	if IsUidGidFromTheImage(spec.UidGidSource) {
		if runAsUid != nil {
			return api.NewValidationError("runAsUid should not be provided when source of uid/gid is fromTheImage")
		}
		if runAsGid != nil {
			return api.NewValidationError("runAsGid should not be provided when source of uid/gid is fromTheImage")
		}
		if supplementalGroups != nil {
			return api.NewValidationError("supplementalGroups should not be provided when source of uid/gid is fromTheImage")
		}
		if spec.OverrideUidGidInWorkspace {
			return api.NewValidationError("overrideUidGidInWorkspace should not be enabled when source of uid/gid is fromTheImage")
		}
	}

	if convutils.Deref(runAsUid, 0) < 0 {
		return api.NewValidationError("the value of runAsUid should be no less than 0")
	}
	if convutils.Deref(runAsGid, 0) < 0 {
		return api.NewValidationError("the value of runAsGid should be no less than 0")
	}

	if supplementalGroups != nil {
		//  for backward compatibility we support both ";" and "," as separator between groups
		normalizedGroups := strings.ReplaceAll(*supplementalGroups, ";", ",")

		groups := strings.Split(normalizedGroups, ",")
		for _, group := range groups {
			groupId, err := strconv.Atoi(group)
			if err != nil {
				return api.NewValidationError(fmt.Sprintf("invalid group id '%s'", group))
			}
			if groupId < 0 {
				return api.NewValidationError(fmt.Sprintf("invalid group id '%s': should be no less than zero", group))
			}
		}
	}

	return nil
}

func ValidateSpecEnvAutoScalingFields(workloadType string, autoScaling *api.SpecificRunAutoScalingAutoScaling) *api.Error {
	if workloadType != auth.WorkloadTypeInference {
		return api.NewValidationError("it is not permitted to specify autoScaling values for workload type other than Inference")
	}
	if autoScaling.MinReplicas != nil && autoScaling.MaxReplicas == nil {
		return api.NewValidationError("autoScaling: maxReplicas is mandatory when minReplicas is provided")
	}
	if autoScaling.MinReplicas == nil && autoScaling.MaxReplicas != nil {
		return api.NewValidationError("autoScaling: minReplicas is mandatory when maxReplicas is provided")
	}
	if autoScaling.MinReplicas != nil && autoScaling.MaxReplicas != nil {
		if *autoScaling.MinReplicas < 0 {
			return api.NewValidationError("autoScaling: minReplicas must be no less than 0")
		}
		if *autoScaling.MinReplicas > *autoScaling.MaxReplicas {
			return api.NewValidationError(fmt.Sprintf("autoScaling: maxReplicas (%d) must be no less than minReplicas (%d)", *autoScaling.MaxReplicas, *autoScaling.MinReplicas))
		}
	}
	if autoScaling.ThresholdMetric != nil && autoScaling.ThresholdValue == nil {
		return api.NewValidationError("autoScaling: thresholdValue is mandatory when thresholdMetric is provided")
	}
	if autoScaling.ThresholdMetric == nil && autoScaling.ThresholdValue != nil {
		return api.NewValidationError("autoScaling: thresholdMetric is mandatory when thresholdValue is provided")
	}
	if autoScaling.ThresholdValue != nil && *autoScaling.ThresholdValue <= 0 {
		return api.NewValidationError("autoScaling: thresholdValue must be greater than 0")
	}
	if autoScaling.ScaleToZeroRetentionSeconds != nil {
		if *autoScaling.ScaleToZeroRetentionSeconds > 0 {
			if autoScaling.MinReplicas == nil || *autoScaling.MinReplicas != 0 {
				return api.NewValidationError("autoScaling: scaleToZeroRetentionSeconds is only supported when minReplicas is 0")
			}
		} else if *autoScaling.ScaleToZeroRetentionSeconds < 0 {
			return api.NewValidationError("autoScaling: scaleToZeroRetentionSeconds must be no less than 0")
		}
	}

	return nil
}

func IsUidGidFromTheImage(uidGidSource *api.UidGidSource) bool {
	return convutils.Deref(uidGidSource, flat_workloads.UidGidFromTheImage) == flat_workloads.UidGidFromTheImage
}
